package org.apache.parquet.filter2;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @TempDir
  Path temporaryDirectory;

  @Test
  void runWritesCompleteBuilderSourceAndClosesOutputFile() throws Exception {
    Path output = temporaryDirectory.resolve("IncrementallyUpdatedFilterPredicateBuilder.java");

    IncrementallyUpdatedFilterPredicateGenerator generator =
        new IncrementallyUpdatedFilterPredicateGenerator(output.toFile());
    generator.run();

    String source = Files.readString(output, StandardCharsets.UTF_8);

    assertTrue(source.startsWith("package org.apache.parquet.filter2.recordlevel;"));
    assertTrue(source.contains(
        "public class IncrementallyUpdatedFilterPredicateBuilder "
            + "extends IncrementallyUpdatedFilterPredicateBuilderBase"));
    assertTrue(source.contains(
        "public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"));

    assertTrue(source.contains("visit(Eq<T> pred)"));
    assertTrue(source.contains("visit(NotEq<T> pred)"));
    assertTrue(source.contains("visit(In<T> pred)"));
    assertTrue(source.contains("visit(NotIn<T> pred)"));
    assertTrue(source.contains("visit(Contains<T> pred)"));
    assertTrue(source.contains("visit(Lt<T> pred)"));
    assertTrue(source.contains("visit(LtEq<T> pred)"));
    assertTrue(source.contains("visit(Gt<T> pred)"));
    assertTrue(source.contains("visit(GtEq<T> pred)"));
    assertTrue(source.contains("visit(UserDefined<T, U> pred)"));
    assertTrue(source.contains("visit(LogicalNotUserDefined<T, U> notPred)"));

    for (String type : new String[] {"Integer", "Long", "Boolean", "Float", "Double", "Binary"}) {
      assertTrue(source.contains("clazz.equals(" + type + ".class)"),
          "Generated source must handle " + type + " predicates");
    }

    assertTrue(source.contains("Operator < not supported for Boolean"));
    assertTrue(source.contains("Operator <= not supported for Boolean"));
    assertTrue(source.contains("Operator > not supported for Boolean"));
    assertTrue(source.contains("Operator >= not supported for Boolean"));

    assertTrue(source.endsWith("}\n"));

    Files.writeString(output, "still writable", StandardCharsets.UTF_8);
    assertEquals("still writable", Files.readString(output, StandardCharsets.UTF_8));
  }
}

package org.apache.parquet.filter2;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;

import org.apache.parquet.filter2.IncrementallyUpdatedFilterPredicateGenerator;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

public class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @Test
  void generatedClassContainsExpectedStructure(@TempDir File tempDir) throws IOException {
    File out = new File(tempDir, "IncrementallyUpdatedFilterPredicateBuilder.java");
    IncrementallyUpdatedFilterPredicateGenerator generator =
        new IncrementallyUpdatedFilterPredicateGenerator(out);
    generator.run();

    String content = Files.readString(out.toPath(), StandardCharsets.UTF_8);

    // Basic structural checks derived from the specification/spec generator output
    assertTrue(content.contains("public class IncrementallyUpdatedFilterPredicateBuilder extends IncrementallyUpdatedFilterPredicateBuilderBase"),
        "Generated file should declare the IncrementallyUpdatedFilterPredicateBuilder class.");
    assertTrue(content.contains("public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"),
        "Generated file should contain the constructor that takes leaves.");

    // Ensure presence of some key generation targets (Eq/NotEq/Contains/UserDefined paths)
    assertTrue(content.contains("Contains") || content.contains("ContainsPredicate"),
        "Generated file should include Contains-related code and predicates.");
    assertTrue(content.contains("UserDefined") || content.contains("visit(UserDefined"),
        "Generated file should include UserDefined predicate handling.");

    // Ensure header comment indicates auto-generation
    assertTrue(content.contains("auto-generated by org.apache.parquet.filter2.IncrementallyUpdatedFilterPredicateGenerator"),
        "Generated file should be labeled as auto-generated by the generator.");
  }

  @Test
  void constructorThrowsIOExceptionIfOutputIsDirectory(@TempDir File tempDir) {
    // Create a directory path and pass it as the output file; FileWriter should fail
    File dir = new File(tempDir, "outputDir");
    dir.mkdirs(); // ensure exists as a directory

    assertThrows(IOException.class, () -> new IncrementallyUpdatedFilterPredicateGenerator(dir));
  }
}
